// Creates and initializes a 3D array with random values in a given range
struct kohonen_array_3d helper_create_3d_array(int dim1, int dim2, int dim3, double min_val, double max_val) {
    struct kohonen_array_3d arr;
    arr.dim1 = dim1;
    arr.dim2 = dim2;
    arr.dim3 = dim3;
    arr.data = (double *)malloc(dim1 * dim2 * dim3 * sizeof(double));
    srand(time(NULL));
    for (int i = 0; i < dim1 * dim2 * dim3; i++) {
        arr.data[i] = min_val + (max_val - min_val) * (rand() % 100) / 100.0;
    }
    return arr;
}

// Frees the memory allocated for a 3D array
void helper_free_3d_array(struct kohonen_array_3d *arr) {
    free(arr->data);
    arr->data = NULL;
}

// Creates and initializes a 2D array with zeros
double** helper_create_2d_array(int rows, int cols) {
    double **arr = (double **)malloc(rows * sizeof(double *));
    for (int i = 0; i < rows; i++) {
        arr[i] = (double *)malloc(cols * sizeof(double));
        for (int j = 0; j < cols; j++) {
            arr[i][j] = 0.0;
        }
    }
    return arr;
}

// Frees the memory allocated for a 2D array
void helper_free_2d_array(double **arr, int rows) {
    for (int i = 0; i < rows; i++) {
        free(arr[i]);
    }
    free(arr);
}


